for q, hits in results.items():
    print("==", q)
    for h in hits:
        print(" -", h.get("title"), "|", h.get("url"))
    print()

# Pull longer text from a few of the high-value papers.
high_value_urls = [
    ("https://www.mdpi.com/2076-3417/15/22/12215",  "Bayesian Optimisation with Dimensionless Groups"),
    ("https://www.mdpi.com/2226-4310/12/6/453",     "Design and Cushioning Performance of Spherical Tensegrity"),
    ("http://arxiv.org/pdf/1609.09049",             "SUPERball planetary lander tensegrity"),
]
for url, name in high_value_urls:
    for q, hits in results.items():
        for h in hits:
            if h.get("url")==url:
                ft = (h.get("full_text") or "")
                print("===", name, "===")
                print(ft[:3000])
                print("...")
                print()
                break

# Get the Dimensionless BO paper key claims:
for q, hits in results.items():
    for h in hits:
        if h.get("url") == "https://www.mdpi.com/2076-3417/15/22/12215":
            ft = h.get("full_text") or ""
            # find passages about "dimensionless" / "Buckingham" / "performance"
            import re
            for m in re.finditer(r"(dimensionless|buckingham|reparame|manifold|scale|pi-group|π-group)", ft, re.I):
                start = max(0, m.start()-200); end = min(len(ft), m.end()+400)
                print(ft[start:end].replace("\n"," "))
                print("---")
            break

# Get the MDPI honeycomb vs foam comparison for actual numbers.
r2 = await web_search("Al honeycomb Al closed cell foam specific absorbed energy MDPI Aerospace 2025", category="scholarly", num_results=3)
for h in r2:
    if "mdpi.com/2226-4310/12/1/32" in (h.get("url") or ""):
        ft = h.get("full_text") or ""
        import re
        for m in re.finditer(r"(specific.{0,5}(absorbed|energy)|SEA|kJ/kg|J/cm3|J/g|MJ/m3)", ft, re.I):
            print(ft[max(0,m.start()-200):m.end()+250].replace("\n", " "))
            print("---")
        break

